        public const string InfernusNativeContract = "own-equipped-gem-and-skilltrigger;native-curse-parent-and-caster;native-timer-snapshot-plus-bounded-difference;refresh-not-additive;restore-own-difference-never-delete-curse;exact-curse-proc-applyelemental-success-and-real-stack-increase;owner-and-target-cd;finite-expired-slot-only-target-ledger;first-native-main-skill-packet-per-activation-ring64;exact-one-firestack-crit-threshold-il-site;preserve-native-high-stack-gate-modifier-and-real-stack-amplification;exclude-generated-origin-other-owner-summon-and-invalid-lifetimes;unique-native-actor-generation-for-curse-gem-owner-victim-and-target-ledger;native-curse-captures-bounded-by-runtime-and-live-native-curse;pool-and-gem-unequip-restore";

        private static BossMoveProfile InfernusProfile(string suffix, string ja, string en, string zh, BossChannelDef[] channels, params BossAction[] actions)
            => new BossMoveProfile("boss_infernus." + suffix, InfernusSetId, new Txt(ja, en, zh), channels, actions);
        private static BossAction InfernusEruptions(BossEvent trigger, string channel, int cooldown, int delay, int interval, int spacing, int radius)
            => new BossAction(trigger, BossMechanism.ShapeAttack, BossPayload.Damage, channel, cooldownMillis: cooldown,
                delayMillis: delay, intervalMillis: interval,count:BossInfernusBalance.EruptionsCount,maxInstances:BossInfernusBalance.EruptionsMaxInstances, radiusMilli: radius,
                rangeMilli: spacing * 3,widthMilli:BossInfernusBalance.EruptionsWidthMilli, magnitudeMilli: spacing, element: BossElement.Fire);
        private static BossAction InfernusRadial(BossEvent trigger, string channel, int cooldown, int delay, int speed, int range, int width, int lifetime, int mainHits = 0)
            => new BossAction(trigger, BossMechanism.Projectile, BossPayload.Damage, channel, BossShape.Radial,
                cooldownMillis: cooldown, delayMillis: delay, lifetimeMillis: lifetime,count:BossInfernusBalance.RadialCount,maxInstances:BossInfernusBalance.RadialMaxInstances,
                mainHits: mainHits,counterLifetimeMillis:BossInfernusBalance.RadialCounterLifetimeMillis, rangeMilli: range, widthMilli: width,
                speedMilli: speed,angleMilli:BossInfernusBalance.RadialAngleMilli, element: BossElement.Fire, followOwner: trigger == BossEvent.Clock);

        internal static BossMoveProfile[] CreateInfernusMoves() => new[]
        {
            InfernusProfile("weapon", "通常攻撃が命中したとき、前方1.5m、3m、4.5mの地点に半径0.8mの噴火を順に起こし、0.30秒後、0.45秒後、0.60秒後に、それぞれ攻撃力・魔力の高い方の10%の火属性ダメージを与える。高低差が2mを超える段差があると、そこから先の噴火は中断される。再発動まで5秒かかる。", "When your basic attack hits, cause eruptions 1.5m, 3m, and 4.5m ahead, each with a 0.8m radius. After 0.30, 0.45, and 0.60 seconds respectively, each deals Fire damage equal to 10% of whichever is higher: your Attack or Ability Power. A terrain step with a height difference greater than 2m stops the remaining eruptions. Cooldown: 5 seconds.", "通常攻击命中时，在前方1.5m、3m、4.5m处依次引发半径0.8m的喷发，分别于0.30秒后、0.45秒后、0.60秒后造成相当于攻击力与法术强度中较高一方10%的火属性伤害。遇到高度差超过2m的台阶时，后续喷发中断。冷却5秒。",
                new[] { C("InfernusEruption",BossInfernusBalance.InfernusEruptionValue,BossInfernusBalance.InfernusEruptionCap) }, InfernusEruptions(BossEvent.MainHit,"InfernusEruption",BossInfernusBalance.WeaponA0CooldownMillis,BossInfernusBalance.WeaponA0DelayMillis,BossInfernusBalance.WeaponA0IntervalMillis,BossInfernusBalance.WeaponA0MagnitudeMilli,BossInfernusBalance.WeaponA0RadiusMilli)),
            InfernusProfile("armor", "ダメージを受けたとき、被弾した自身の位置に予告を出し、0.35秒後に半径2mの範囲へ攻撃力・魔力の高い方の24%の火属性ダメージを与えて、一般の敵を外側へ0.8m押し出す。ボスと行動妨害耐性を持つ敵は動かない。再発動まで7秒かかる。", "When you take damage, show a warning at your position at the time of the hit for 0.35 seconds, then deal Fire damage in a 2m radius equal to 24% of whichever is higher: your Attack or Ability Power and push normal enemies outward by 0.8m. Bosses and enemies immune to crowd control are not moved. Cooldown: 7 seconds.", "受到伤害时，在受击时自身的位置显示预警，0.35秒后对半径2m范围造成相当于攻击力与法术强度中较高一方24%的火属性伤害，并将普通敌人向外推开0.8m。首领和免疫控制的敌人不会被移动。冷却7秒。",
                new[] { C("InfernusLanding",BossInfernusBalance.InfernusLandingValue,BossInfernusBalance.InfernusLandingCap) },
                new BossAction(BossEvent.NativeDamageTaken,BossMechanism.ShapeAttack,BossPayload.Push,"InfernusLanding",cooldownMillis:BossInfernusBalance.ArmorA0CooldownMillis,delayMillis:BossInfernusBalance.ArmorA0DelayMillis,maxInstances:BossInfernusBalance.ArmorA0MaxInstances,radiusMilli:BossInfernusBalance.ArmorA0RadiusMilli,magnitudeMilli:BossInfernusBalance.ArmorA0MagnitudeMilli,element:BossElement.Fire)),
            InfernusProfile("charm", "記憶を使ったとき、カーソル位置（8m以内）に、1.5秒間続く炎の柱を召喚する。炎の柱は0.50秒後に半径1.5mの範囲へ攻撃力・魔力の高い方の16%のダメージを与え、その後0.5秒間隔で3回、各6%のダメージを与える。炎の柱は同時に1本までしか出せない。再発動まで8秒かかる。", "When you use a memory, summon a flame pillar at the cursor within 8m, lasting 1.5 seconds. After 0.50 seconds, it deals damage in a 1.5m radius equal to 16% of whichever is higher: your Attack or Ability Power, then deals 6% damage 3 times at 0.5-second intervals. Only one pillar can exist at once. Cooldown: 8 seconds.", "使用记忆时，在光标位置（8m以内）召唤持续1.5秒的火柱。0.50秒后对半径1.5m范围造成相当于攻击力与法术强度中较高一方16%的伤害，随后以0.5秒的间隔造成3次各6%的伤害。同时最多存在1根火柱。冷却8秒。",
                new[] { C("InfernusPillarInitial",BossInfernusBalance.InfernusPillarInitialValue,BossInfernusBalance.InfernusPillarInitialCap), C("InfernusPillarTick",BossInfernusBalance.InfernusPillarTickValue,BossInfernusBalance.InfernusPillarTickCap) },
                new BossAction(BossEvent.MemoryUse,BossMechanism.ShapeAttack,BossPayload.Damage,"InfernusPillarInitial",anchor:BossAnchor.Cursor,cooldownMillis:BossInfernusBalance.CharmA0CooldownMillis,delayMillis:BossInfernusBalance.CharmA0DelayMillis,lifetimeMillis:BossInfernusBalance.CharmA0LifetimeMillis,maxInstances:BossInfernusBalance.CharmA0MaxInstances,radiusMilli:BossInfernusBalance.CharmA0RadiusMilli,rangeMilli:BossInfernusBalance.CharmA0RangeMilli,element:BossElement.Fire),
                new BossAction(BossEvent.Clock,BossMechanism.ShapeAttack,BossPayload.Damage,"InfernusPillarTick",delayMillis:BossInfernusBalance.CharmA1DelayMillis,lifetimeMillis:BossInfernusBalance.CharmA1LifetimeMillis,intervalMillis:BossInfernusBalance.CharmA1IntervalMillis,count:BossInfernusBalance.CharmA1Count,maxInstances:BossInfernusBalance.CharmA1MaxInstances,radiusMilli:BossInfernusBalance.CharmA1RadiusMilli,element:BossElement.Fire)),
            InfernusProfile("head", "記憶を使ったとき、発動時の方向へ長さ5m・幅1mの炎を、0秒後、0.2秒後、0.4秒後の3回放射し、そのたびに攻撃力・魔力の高い方の12%のダメージを与える。炎の持続は0.6秒で、同じ敵に当たるのは各回1回まで。再発動まで7秒かかる。", "When you use a memory, release flames in the direction you were facing at activation along a line 5m long and 1m wide, at 0, 0.2, and 0.4 seconds. Each deals 12% of whichever is higher: your Attack or Ability Power. The effect lasts 0.6 seconds, and each enemy can be hit only once per burst. Cooldown: 7 seconds.", "使用记忆时，朝发动时的方向沿长5m、宽1m的直线喷射火焰，分别在0秒后、0.2秒后、0.4秒后发动，每次造成相当于攻击力与法术强度中较高一方12%的伤害。火焰持续0.6秒，每次喷射对同一敌人最多命中1次。冷却7秒。",
                new[] { C("InfernusBreath",BossInfernusBalance.InfernusBreathValue,BossInfernusBalance.InfernusBreathCap) },
                new BossAction(BossEvent.MemoryUse,BossMechanism.ShapeAttack,BossPayload.Damage,"InfernusBreath",BossShape.Line,cooldownMillis:BossInfernusBalance.HeadA0CooldownMillis,lifetimeMillis:BossInfernusBalance.HeadA0LifetimeMillis,intervalMillis:BossInfernusBalance.HeadA0IntervalMillis,count:BossInfernusBalance.HeadA0Count,maxInstances:BossInfernusBalance.HeadA0MaxInstances,rangeMilli:BossInfernusBalance.HeadA0RangeMilli,widthMilli:BossInfernusBalance.HeadA0WidthMilli,element:BossElement.Fire)),
            InfernusProfile("hands", "6秒以内に通常攻撃が3回命中すると、予告を出し、0.35秒後に4方向へ咆哮弾を放つ。咆哮弾の弾速は10m/秒、射程は4m、幅は0.5m、持続は0.4秒。ダメージは各5%で、同じ敵には合計で攻撃力・魔力の高い方の20%まで与える。再発動まで6秒かかる。", "After 3 basic attack hits within 6 seconds, show a warning for 0.35 seconds, then fire roar projectiles in 4 directions. They travel at 10m/s, have a 4m range, are 0.5m wide, and last 0.4 seconds. Each deals 5% of whichever is higher: your Attack or Ability Power, up to a total of 20% per enemy. Cooldown: 6 seconds.", "6秒内通常攻击命中3次后，显示预警，0.35秒后向4个方向发射咆哮弹。弹速10m/秒，射程4m，宽0.5m，持续0.4秒。每枚造成相当于攻击力与法术强度中较高一方5%的伤害，对同一敌人的合计伤害不超过20%。冷却6秒。",
                new[] { C("InfernusRoar",BossInfernusBalance.InfernusRoarValue,BossInfernusBalance.InfernusRoarCap) }, InfernusRadial(BossEvent.MainHit,"InfernusRoar",BossInfernusBalance.HandsA0CooldownMillis,BossInfernusBalance.HandsA0DelayMillis,BossInfernusBalance.HandsA0SpeedMilli,BossInfernusBalance.HandsA0RangeMilli,BossInfernusBalance.HandsA0WidthMilli,BossInfernusBalance.HandsA0LifetimeMillis,BossInfernusBalance.HandsA0MainHits)),
            InfernusProfile("feet", "移動スキルが終わったとき、前方の長さ3m・幅1.5mの範囲に攻撃力・魔力の高い方の18%のダメージを与え、敵を1.2m押し出す。敵は壁で止まり、ボスと行動妨害が効かない敵は動かない。再発動まで5秒かかる。", "When your movement skill ends, deal damage in an area 3m long and 1.5m wide ahead of you equal to 18% of whichever is higher: your Attack or Ability Power, and push enemies 1.2m. Movement stops at walls; bosses and enemies immune to crowd control are not moved. Cooldown: 5 seconds.", "移动技能结束时，对前方长3m、宽1.5m的范围造成相当于攻击力与法术强度中较高一方18%的伤害，并将敌人推开1.2m。敌人遇墙停止，首领和免疫控制的敌人不会被移动。冷却5秒。",
                new[] { C("InfernusDashImpact",BossInfernusBalance.InfernusDashImpactValue,BossInfernusBalance.InfernusDashImpactCap) },
                new BossAction(BossEvent.MovementCompleted,BossMechanism.ShapeAttack,BossPayload.Push,"InfernusDashImpact",BossShape.Line,cooldownMillis:BossInfernusBalance.FeetA0CooldownMillis,maxInstances:BossInfernusBalance.FeetA0MaxInstances,rangeMilli:BossInfernusBalance.FeetA0RangeMilli,widthMilli:BossInfernusBalance.FeetA0WidthMilli,magnitudeMilli:BossInfernusBalance.FeetA0MagnitudeMilli,element:BossElement.Fire)),
            InfernusProfile("stage2", "通常攻撃が命中するか、記憶を使ったとき、熱の印を1つ得る。熱の印の持続は6秒で、最大3個までためられる。印が3個ある状態で次に通常攻撃を命中させるか記憶を使うと、全て消費して、前方2m、4m、6mの地点に半径1mの噴火を起こす。噴火は0.35秒、0.55秒、0.75秒の予告の後に発生し、それぞれ攻撃力・魔力の高い方の12%の火属性ダメージを与える。高低差が2mを超える段差があると、そこから先の噴火は中断される。再発動まで4秒かかる。", "When your basic attack hits or you use a memory, gain one heat mark, lasting 6 seconds and stacking up to 3 times. With 3 marks, your next basic attack hit or memory use consumes them all to cause eruptions 2m, 4m, and 6m ahead in a 1m radius, after warnings lasting 0.35, 0.55, and 0.75 seconds respectively. Each deals Fire damage equal to 12% of whichever is higher: your Attack or Ability Power. A terrain step with a height difference greater than 2m stops the remaining eruptions. Cooldown: 4 seconds.", "通常攻击命中或使用记忆时，获得1个热之印记，持续6秒，最多积累3个。持有3个印记时，下一次通常攻击命中或使用记忆会消耗全部印记，在前方2m、4m、6m处引发半径1m的喷发，分别在0.35秒、0.55秒、0.75秒的预警后造成相当于攻击力与法术强度中较高一方12%的火属性伤害。遇到高度差超过2m的台阶时，后续喷发中断。冷却4秒。",
                new[] { C("InfernusHeatEruption",BossInfernusBalance.InfernusHeatEruptionValue,BossInfernusBalance.InfernusHeatEruptionCap) },
                new BossAction(BossEvent.MainHit,BossMechanism.Ledger,BossPayload.Mark,count:BossInfernusBalance.Stage2A0Count,lifetimeMillis:BossInfernusBalance.Stage2A0LifetimeMillis,maxInstances:BossInfernusBalance.Stage2A0MaxInstances,element:BossElement.Fire),
                InfernusEruptions(BossEvent.Clock,"InfernusHeatEruption",BossInfernusBalance.Stage2A1CooldownMillis,BossInfernusBalance.Stage2A1DelayMillis,BossInfernusBalance.Stage2A1IntervalMillis,BossInfernusBalance.Stage2A1MagnitudeMilli,BossInfernusBalance.Stage2A1RadiusMilli)),
            InfernusProfile("stage3", "2セット効果の噴火列の最終地点に予告を出し、0.8秒後に、2秒間続く半径2mの炎柱を召喚する。炎柱は0.5秒間隔で4回、各攻撃力・魔力の高い方の8%のダメージを与える。炎柱は同時に1本までしか出せない。", "At the final location of the 2-piece eruption sequence, show a warning for 0.8 seconds, then summon a flame pillar with a 2m radius for 2 seconds. It deals damage 4 times at 0.5-second intervals, each equal to 8% of whichever is higher: your Attack or Ability Power. Only one pillar can exist at once.", "在2件套喷发序列的最后地点显示预警，0.8秒后召唤半径2m的火柱，持续2秒。火柱以0.5秒的间隔造成4次伤害，每次相当于攻击力与法术强度中较高一方的8%。同时最多存在1根火柱。",
                new[] { C("InfernusHeatPillar",BossInfernusBalance.InfernusHeatPillarValue,BossInfernusBalance.InfernusHeatPillarCap) },
                new BossAction(BossEvent.Clock,BossMechanism.ShapeAttack,BossPayload.Damage,"InfernusHeatPillar",delayMillis:BossInfernusBalance.Stage3A0DelayMillis,lifetimeMillis:BossInfernusBalance.Stage3A0LifetimeMillis,intervalMillis:BossInfernusBalance.Stage3A0IntervalMillis,count:BossInfernusBalance.Stage3A0Count,maxInstances:BossInfernusBalance.Stage3A0MaxInstances,radiusMilli:BossInfernusBalance.Stage3A0RadiusMilli,element:BossElement.Fire)),
            InfernusProfile("stage6", "2セット効果が発動した1秒後、自身の位置から4方向へ咆哮弾を放つ。咆哮弾の弾速は12m/秒、射程は6m、幅は0.7m、持続は0.5秒。ダメージは各22.5%で、同じ敵には合計で攻撃力・魔力の高い方の90%（上限100%）まで与える。同時に、攻撃力・魔力の高い方の38%（上限40%）の障壁を2秒間得る。障壁は重ならない。再発動まで10秒かかる。", "One second after the 2-piece effect activates, fire roar projectiles from your position in 4 directions. They travel at 12m/s, have a 6m range, are 0.7m wide, and last 0.5 seconds. Each deals 22.5% of whichever is higher: your Attack or Ability Power, up to a total of 90% per enemy (cap: 100%). At the same time, gain a shield for 2 seconds equal to 38% (cap: 40%; does not stack). Cooldown: 10 seconds.", "2件套效果发动1秒后，从自身位置向4个方向发射咆哮弹。弹速12m/秒，射程6m，宽0.7m，持续0.5秒。每枚造成相当于攻击力与法术强度中较高一方22.5%的伤害，对同一敌人的合计伤害最多为90%（上限100%）。同时获得相当于攻击力与法术强度中较高一方38%（上限40%）的护盾，持续2秒。护盾不叠加。冷却10秒。",
                new[] { C("InfernusBurst",BossInfernusBalance.InfernusBurstValue,BossInfernusBalance.InfernusBurstCap), C("InfernusBurstShield",BossInfernusBalance.InfernusBurstShieldValue,BossInfernusBalance.InfernusBurstShieldCap,BossCoefficientKind.Shield) },
                InfernusRadial(BossEvent.Clock,"InfernusBurst",BossInfernusBalance.Stage6A0CooldownMillis,BossInfernusBalance.Stage6A0DelayMillis,BossInfernusBalance.Stage6A0SpeedMilli,BossInfernusBalance.Stage6A0RangeMilli,BossInfernusBalance.Stage6A0WidthMilli,BossInfernusBalance.Stage6A0LifetimeMillis),
                new BossAction(BossEvent.Clock,BossMechanism.Defense,BossPayload.Shield,"InfernusBurstShield",delayMillis:BossInfernusBalance.Stage6A1DelayMillis,lifetimeMillis:BossInfernusBalance.Stage6A1LifetimeMillis,maxInstances:BossInfernusBalance.Stage6A1MaxInstances,element:BossElement.Fire,followOwner:true)),
        };

        internal static BossRewardProfile[] CreateInfernusRewards()
        {
            BossRewardAction Timer() => new BossRewardAction(BossRewardActionKind.NativeInterval,BossInfernusBalance.RewardTimerValueMilli,BossInfernusBalance.RewardTimerCapMilli,durationMillis:BossInfernusBalance.RewardTimerDurationMillis,order:0);
            BossRewardAction Stack() => new BossRewardAction(BossRewardActionKind.NativeState,BossInfernusBalance.RewardStackValueMilli,BossInfernusBalance.RewardStackCapMilli,cooldownMillis:BossInfernusBalance.RewardStackCooldownMillis,durationMillis:BossInfernusBalance.RewardStackDurationMillis,count:BossInfernusBalance.RewardStackCount,order:1);
            BossRewardAction Crit() => new BossRewardAction(BossRewardActionKind.NativeDamage,BossInfernusBalance.RewardCritValueMilli,BossInfernusBalance.RewardCritCapMilli,cooldownMillis:BossInfernusBalance.RewardCritCooldownMillis,count:BossInfernusBalance.RewardCritCount,order:2);
            return new[] { new BossRewardProfile(InfernusRewardId,InfernusSetId,"Gem_U_EternalFlame",BossRewardAdapter.EternalFlame,new[]
            {
                new BossRewardStage(1,new Txt("自身が装着している「エターナルフレイム」由来の呪いの持続時間と残り時間を、1秒延ばす。効果が更新されたときも同じである。装備を外すと、延ばした分だけが元に戻る。呪い自体は解除されない。", "Extend the duration and remaining time of curses from your equipped Eternal Flame by 1 second, including when the effect refreshes. Unequipping removes only the extension, not the curse itself.", "将自身装备的“永恒之焰”所施加诅咒的持续时间和剩余时间延长1秒，效果刷新时也相同。卸下装备后，仅撤销延长的时间，诅咒本身不会被解除。"),new[] { Timer() }),
                new BossRewardStage(2,new Txt("固有報酬の段階1の効果に加え、自身の直接攻撃で呪いの効果が発動して火傷（Fire）が蓄積したとき、火傷を追加で1スタック付与する。同じ敵には2秒に1回まで、最大3体まで個別に管理し、自身の再発動まで1秒かかる。召喚や間接ダメージでは発動しない。", "In addition to boss reward stage 1, when your direct attack triggers your curse and adds a Burn (Fire) stack, add one extra Burn stack. Cooldown: 2 seconds per enemy, tracked separately for up to 3 enemies, and 1 second for you. Summons and indirect damage cannot trigger this effect.", "除首领专属奖励阶段1的效果外，自身直接攻击触发诅咒并增加灼烧（Fire）层数时，额外施加1层灼烧。对同一敌人每2秒最多触发1次，最多分别记录3名敌人，自身冷却1秒。召唤物和间接伤害无法触发。"),new[] { Timer(),Stack() }),
                new BossRewardStage(3,new Txt("固有報酬の段階2の効果に加え、自身の呪いと火傷（Fire）が3〜4スタック付与されている敵1体に対して、「エターナルフレイム」を装着した記憶スキルを発動したときの最初の主要ダメージが会心になるために必要な火傷スタック数が、「5」から「3」に緩和される。再発動まで4秒かかり、1回の発動につき1回だけ有効である。", "In addition to boss reward stage 2, against one enemy affected by your curse and 3–4 Burn (Fire) stacks, reduce the required Burn stacks from 5 to 3 for the first main damage of a memory skill equipped with Eternal Flame to critically strike. Cooldown: 4 seconds, once per activation.", "除首领专属奖励阶段2的效果外，对受到自身诅咒且带有3～4层灼烧（Fire）的1名敌人，施放装有“永恒之焰”的记忆技能时，其首次主要伤害触发暴击所需的灼烧层数从5层降为3层。冷却4秒，每次施放仅生效1次。"),new[] { Timer(),Stack(),Crit() }),
            }) };
        }

